import json,runpy,signal,time
from pathlib import Path
R=Path('/Users/mustafaerbay/IdeaProjects/zee-urunlesme-20261014');E=Path('/Users/mustafaerbay/.codex/zee-evidence/2026-10-14-urunlesme')
O=E/'p19-k298-source-gates-2';assert not O.exists();O.mkdir(mode=0o700)
H=runpy.run_path(str(R/'scripts/lifecycle_core.py'));env=H['controlled_env']();env.update(RUSTUP_TOOLCHAIN='1.93.1',CARGO_BUILD_JOBS='1',RUST_TEST_THREADS='1',CARGO_NET_OFFLINE='true')
for n in [signal.SIGTERM,signal.SIGINT]:signal.signal(n,lambda *_: H['run'].__globals__.__setitem__('CANCELLED',True))
prior=json.loads((E/'p19-k298-source-gates-1/PROOF.json').read_text());assert prior['status']=='failed';assert all(c['status']=='passed' for c in prior['commands'][:-1]);assert prior['commands'][-1]['name']=='function-trend';assert 'işlev eğilim raporu bayat' in (E/'p19-k298-source-gates-1/function-trend.log').read_text()
source_pins={x:H['digest'](R/x) for x in ['compiler/src/lsp.rs','compiler/src/lsp/analiz.rs','compiler/tests/lsp_artimli_testi.rs']}
proof={'prior_proof_sha256':H['digest'](E/'p19-k298-source-gates-1/PROOF.json'),'prior_passed_commands':prior['commands'][:-1],'source_pins':source_pins,'status':'running','source_parent':H['git'](R,'rev-parse','HEAD'),'commands':[],'driver_sha256':H['digest'](Path(__file__))}
def save(): (O/'PROOF.json').write_text(json.dumps(proof,indent=2)+'\n')
def run(name,args,cwd=R/'compiler',timeout=900):
 c={'name':name,'argv':args,'status':'running'};proof['commands'].append(c);save();start=time.monotonic();log=O/(name+'.log')
 try:H['run'](args,cwd=cwd,timeout=timeout,limit=24*1024**2,env=env,log_path=log);c.update(status='passed',exit=0);print(name+': passed',flush=True)
 finally:
  c['seconds']=time.monotonic()-start
  if log.exists():c['log_sha256']=H['digest'](log)
  save()
try:
 run('function-report',['cargo','run','--locked','--bin','islev_egilimi','--','--rapor-yaz'])
 run('documentation',['cargo','test','--locked','--test','katalog_testi','--test','dokuman_tazelik_testi'])
 run('function-trend',['cargo','run','--locked','--bin','islev_egilimi','--','--denetle'])
 run('spec-drift',['cargo','run','--locked','--bin','spec_drift','--','--denetle'])
 run('fmt-check',['cargo','fmt','--all','--','--check'])
 for name in ['conformance','semantic-regresyon','core-freeze']:run(name+'-guard',['bash','scripts/'+name+'-korugu.sh',proof['source_parent']],cwd=R)
 run('diff-check',['git','diff','--check'],cwd=R)
 run('secret-scan',['bash','scripts/sir-taramasi.sh'],cwd=R,timeout=900)
 assert source_pins=={x:H['digest'](R/x) for x in source_pins}
 proof['status']='passed'
except BaseException as error:proof.update(status='failed',failure_type=type(error).__name__);raise
finally:save()
